MERGE INTO DB1.S2.T1 t
USING (
    SELECT C1, C2 FROM DB1.S1.V1 WHERE "Col_B" = 'A'
) src
ON  t.C1 = src.C1
WHEN MATCHED AND (NOT EQUAL_NULL(t.C2, src.C2)) THEN UPDATE SET
    t.C2 = src.C2,
    t.C6 = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN INSERT
    (C1, C2, C6)
    VALUES
    (src.C1, src.C2, CURRENT_TIMESTAMP());
